async def act(page):
    import asyncio
    import re

    # Navigate to the Sales Orders grid using a relative URL (deterministic)
    await page.goto('/index.php/admin/sales_order/')

    # Wait for at least one table to render
    tables = page.get_by_role('table')
    for _ in range(40):
        if await tables.count() > 0:
            break
        await asyncio.sleep(0.25)
    else:
        raise RuntimeError('No table found on the Sales Orders page')

    # Locate the orders table by looking for header text 'Status' and 'Grand Total'
    orders_table = None
    table_count = await tables.count()
    for i in range(table_count):
        tbl = tables.nth(i)
        try:
            txt = (await tbl.inner_text()).lower()
        except Exception:
            continue
        if 'status' in txt and 'grand total' in txt:
            orders_table = tbl
            break

    # Looser fallback: pick first table containing 'status' and something like 'order' or 'grand'
    if orders_table is None:
        for i in range(table_count):
            tbl = tables.nth(i)
            try:
                txt = (await tbl.inner_text()).lower()
            except Exception:
                continue
            if 'status' in txt and ('order' in txt or 'grand' in txt):
                orders_table = tbl
                break

    if orders_table is None:
        raise RuntimeError('Could not locate the Orders grid table (missing expected headers)')

    # Get rows from the orders table
    rows = orders_table.get_by_role('row')
    if await rows.count() == 0:
        raise RuntimeError('Orders table has no rows')

    # Header is usually the first row
    header_row = rows.nth(0)
    header_cells = header_row.get_by_role('columnheader')
    if await header_cells.count() == 0:
        header_cells = header_row.get_by_role('cell')

    header_count = await header_cells.count()
    headers = []
    for hi in range(header_count):
        try:
            htxt = (await header_cells.nth(hi).inner_text()).strip()
        except Exception:
            htxt = ''
        headers.append(htxt)

    idx_status = None
    idx_grand = None
    for idx, h in enumerate(headers):
        low = h.lower()
        if idx_status is None and 'status' in low:
            idx_status = idx
        if idx_grand is None and ('grand total' in low or 'grand' == low.strip() or 'grand_total' in low):
            idx_grand = idx

    # Fallback: tokenize header row text if indices not found
    if idx_status is None or idx_grand is None:
        try:
            hdr_text = (await header_row.inner_text())
        except Exception:
            hdr_text = '\n'.join(headers)
        tokens = re.split(r'\t|\n| {2,}', hdr_text)
        for idx, t in enumerate(tokens):
            tl = t.strip().lower()
            if idx_status is None and 'status' in tl:
                idx_status = idx
            if idx_grand is None and 'grand total' in tl:
                idx_grand = idx

    if idx_status is None or idx_grand is None:
        raise RuntimeError('Could not determine header indexes for Status and Grand Total')

    # Helper to parse currency-like strings to float
    def parse_currency_to_float(s: str) -> float:
        if s is None:
            return 0.0
        s = s.replace('\u00a0', ' ').strip()
        if s == '':
            return 0.0
        neg = False
        if '(' in s and ')' in s:
            neg = True
        cleaned = re.sub(r"[^0-9.,\-()]+", '', s)
        cleaned = cleaned.replace('(', '').replace(')', '')
        cleaned = cleaned.replace(',', '')
        if cleaned in ('', '.', '-', '-.'):
            return 0.0
        try:
            val = float(cleaned)
        except Exception:
            m = re.search(r'-?\d+[\d\.]*', cleaned)
            if m:
                try:
                    val = float(m.group(0))
                except Exception:
                    val = 0.0
            else:
                val = 0.0
        if neg:
            val = -abs(val)
        return val

    # Iterate data rows and collect grand totals of the first 2 completed orders
    completed_totals = []
    total_rows = await rows.count()
    for r in range(1, total_rows):
        row = rows.nth(r)
        cells = row.get_by_role('cell')
        cnt = await cells.count()
        if cnt == 0:
            continue
        try:
            status_text = (await cells.nth(idx_status).inner_text()).strip() if idx_status < cnt else (await row.inner_text()).strip()
        except Exception:
            try:
                status_text = (await row.inner_text()).strip()
            except Exception:
                status_text = ''
        if 'complete' not in status_text.lower():
            continue
        try:
            if idx_grand < cnt:
                grand_text = (await cells.nth(idx_grand).inner_text()).strip()
            else:
                row_text = (await row.inner_text()).strip()
                tokens = re.split(r'\t|\n| {2,}', row_text)
                grand_text = tokens[-1] if tokens else ''
        except Exception:
            try:
                row_text = (await row.inner_text()).strip()
                tokens = re.split(r'\t|\n| {2,}', row_text)
                grand_text = tokens[-1] if tokens else ''
            except Exception:
                grand_text = ''

        val = parse_currency_to_float(grand_text)
        completed_totals.append(val)
        if len(completed_totals) >= 2:
            break

    if len(completed_totals) == 0:
        raise RuntimeError('No completed orders found')

    total_sum = sum(completed_totals[:2])
    # Return the numeric result as a plain string with two decimals
    return f"{total_sum:.2f}"

